logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


@asynccontextmanager
async def lifespan(app: FastAPI):
    Base.metadata.create_all(bind=engine)
    app.state.router = ProcessorRouter()
    app.state.circuit_breakers = {
        "stripe": CircuitBreaker(
            processor="stripe",
            failure_threshold=settings.circuit_breaker_failure_threshold,
            timeout_seconds=settings.circuit_breaker_timeout_seconds,
        )
    }
    logger.info("Bank Connector started")
    yield
    logger.info("Bank Connector stopped")


app = FastAPI(title="bank_connector", version="1.0.0", lifespan=lifespan)


def _save_transaction(
        db: Session,
        request,
        operation: str,
        response: ProcessorResponse,
        processor: str,
        duration_ms: int,
        retry_count: int = 0,
) -> ProcessorTransaction:
    """Save every processor call to the audit log"""
    tx = ProcessorTransaction(
        id=f"ptx_{uuid.uuid4().hex[:18]}",
        payment_id=request.payment_id,
        merchant_id=request.merchant_id,
        idempotency_key=getattr(request, "idempotency_key", None),
        operation=operation,
        processor=processor,
        amount=getattr(request, "amount", 0),
        currency=getattr(request, "currency", "usd"),
        card_last4=response.card_last4,
        card_brand=response.card_brand,
        success=response.success,
        processor_id=response.processor_id,
        authorization_code=response.authorization_code,
        processor_response=response.raw_response,
        failure_code=response.failure_code,
        failure_message=response.failure_message,
        decline_code=response.decline_code,
        duration_ms=duration_ms,
        retry_count=retry_count,
    )
    db.add(tx)
    db.commit()
    return tx


