@app.get("/health", response_model=HealthResponse)
async def health():
    stripe_ok = True
    try:
        import stripe as stripe_lib
        stripe_lib.api_key = settings.stripe_secret_key
        if settings.stripe_secret_key != "sk_test_placeholder":
            stripe_lib.Account.retrieve()
    except Exception:
        stripe_ok = False

    cb_status = {}
    for name, cb in app.state.circuit_breakers.items():
        cb_status[name] = cb.get_status()

    return HealthResponse(
        status="ok",
        service="bank_connector",
        stripe_connected=stripe_ok,
        circuit_breakers=cb_status,
    )


# ============================================================================
# AUTHORIZE
# ============================================================================

@app.post("/authorize", response_model=ProcessorResponse)
async def authorize(
        request: AuthorizeRequest,
        db: Session = Depends(get_db),
):
    """
    Authorize (hold) funds on customer's card.

    Flow:
    1. Check idempotency (prevent double charges)
    2. Check circuit breaker (fail fast if Stripe is down)
    3. Route to correct processor
    4. Call processor
    5. Record result
    6. Update circuit breaker
    7. Return normalized response
    """

    # ── Idempotency ──────────────────────────────────────────────────
    if request.idempotency_key:
        existing = get_existing_transaction(
            db, request.idempotency_key, request.payment_id, "authorize"
        )
        if existing:
            return ProcessorResponse(
                success=existing.success,
                processor=existing.processor,
                processor_id=existing.processor_id,
                authorization_code=existing.authorization_code,
                card_last4=existing.card_last4,
                card_brand=existing.card_brand,
                raw_response={"idempotent": True, **(existing.processor_response or {})},
            )

    # ── Circuit Breaker ───────────────────────────────────────────────
    processor = app.state.router.get_processor(request)
    cb = app.state.circuit_breakers.get(processor.name)

    if cb and not cb.can_attempt():
        raise HTTPException(
            status_code=503,
            detail={
                "error": "processor_unavailable",
                "message": f"Payment processor {processor.name} is temporarily unavailable",
                "retry_after": settings.circuit_breaker_timeout_seconds,
            },
        )

    # ── Process ───────────────────────────────────────────────────────
    start = time.time()
    try:
        response = await processor.authorize(request)
        duration_ms = int((time.time() - start) * 1000)

        # Update circuit breaker
        if cb:
            if response.success:
                cb.record_success()
            else:
                # Only count as circuit failure if it's a processor issue
                # NOT if it's a card decline (that's user error)
                if response.failure_code not in ("card_declined", "insufficient_funds", "stolen_card", "lost_card"):
                    cb.record_failure()

        # Save audit log
        _save_transaction(db, request, "authorize", response, processor.name, duration_ms)

        if not response.success:
            raise HTTPException(
                status_code=402,
                detail={
                    "error": "payment_failed",
                    "code": response.failure_code,
                    "message": response.failure_message,
                    "decline_code": response.decline_code,
                },
            )

        return response

    except HTTPException:
        raise
    except Exception as e:
        duration_ms = int((time.time() - start) * 1000)
        if cb:
            cb.record_failure()

        error_response = ProcessorResponse(
            success=False,
            processor=processor.name,
            failure_code="processor_error",
            failure_message=str(e),
        )
        _save_transaction(db, request, "authorize", error_response, processor.name, duration_ms)
        logger.error(f"Authorize error: payment={request.payment_id} error={e}")
        raise HTTPException(status_code=502, detail={"error": "processor_error", "message": str(e)})


