@app.post("/capture", response_model=ProcessorResponse)
async def capture(
        request: CaptureRequest,
        db: Session = Depends(get_db),
):
    """Capture previously authorized funds"""

    # Idempotency check
    if request.idempotency_key:
        existing = get_existing_transaction(
            db, request.idempotency_key, request.payment_id, "capture"
        )
        if existing:
            return ProcessorResponse(
                success=existing.success,
                processor=existing.processor,
                capture_reference=existing.processor_id,
                raw_response={"idempotent": True},
            )

    processor = app.state.router.processors.get("stripe")
    cb = app.state.circuit_breakers.get("stripe")

    if cb and not cb.can_attempt():
        raise HTTPException(503, detail={"error": "processor_unavailable"})

    start = time.time()
    try:
        response = await processor.capture(request)
        duration_ms = int((time.time() - start) * 1000)

        if cb:
            cb.record_success() if response.success else cb.record_failure()

        _save_transaction(db, request, "capture", response, processor.name, duration_ms)

        if not response.success:
            raise HTTPException(
                status_code=502,
                detail={"error": "capture_failed", "message": response.failure_message},
            )

        return response

    except HTTPException:
        raise
    except Exception as e:
        if cb:
            cb.record_failure()
        raise HTTPException(502, detail={"error": "processor_error", "message": str(e)})


