@app.get("/transactions/{payment_id}")
async def get_transactions(payment_id: str, db: Session = Depends(get_db)):
    """Full audit trail for a payment"""
    txs = (
        db.query(ProcessorTransaction)
        .filter(ProcessorTransaction.payment_id == payment_id)
        .order_by(ProcessorTransaction.created_at.asc())
        .all()
    )
    return {
        "payment_id": payment_id,
        "total": len(txs),
        "transactions": [
            {
                "id": t.id,
                "operation": t.operation,
                "processor": t.processor,
                "success": t.success,
                "amount": t.amount,
                "currency": t.currency,
                "processor_id": t.processor_id,
                "authorization_code": t.authorization_code,
                "failure_code": t.failure_code,
                "failure_message": t.failure_message,
                "decline_code": t.decline_code,
                "duration_ms": t.duration_ms,
                "retry_count": t.retry_count,
                "created_at": t.created_at.isoformat(),
            }
            for t in txs
        ],
    }


@app.get("/stats")
async def get_stats(db: Session = Depends(get_db)):
    """Processor performance stats"""
    total = db.query(ProcessorTransaction).count()
    successful = db.query(ProcessorTransaction).filter(ProcessorTransaction.success).count()
    failed = db.query(ProcessorTransaction).filter(~ProcessorTransaction.success).count()

    cb_status = {
        name: cb.get_status()
        for name, cb in app.state.circuit_breakers.items()
    }

    return {
        "total_transactions": total,
        "successful": successful,
        "failed": failed,
        "success_rate": round(successful / total * 100, 2) if total else 0,
        "circuit_breakers": cb_status,
    }
